import{_ as t,o as a,c as r,a3 as d}from"./chunks/framework.DotktHmf.js";const u=JSON.parse('{"title":"Memory budget","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://kilnrender.com/architecture/memory-budget.html"}],["meta",{"property":"og:title","content":"Memory budget | Kiln"}],["meta",{"property":"og:description","content":"A WebGPU renderer that streams large volumetric datasets over HTTP into a bounded VRAM cache."}],["meta",{"property":"og:url","content":"https://kilnrender.com/architecture/memory-budget.html"}],["meta",{"name":"twitter:title","content":"Memory budget | Kiln"}],["meta",{"name":"twitter:description","content":"A WebGPU renderer that streams large volumetric datasets over HTTP into a bounded VRAM cache."}]]},"headers":[],"relativePath":"architecture/memory-budget.md","filePath":"architecture/memory-budget.md"}'),o={name:"architecture/memory-budget.md"};function s(n,e,i,h,l,c){return a(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="memory-budget" tabindex="-1">Memory budget <a class="header-anchor" href="#memory-budget" aria-label="Permalink to &quot;Memory budget&quot;">​</a></h1><p>The atlas is sized from the budget (<code>atlasBudgetBytes</code>, default ~1.3 GiB), not from the dataset: a 100 MB and a 100 GB volume get the same atlas. For a 1024 × 512 × 1024 volume at the full 660³ atlas:</p><table tabindex="0"><thead><tr><th>Resource</th><th>8-bit</th><th>16-bit</th><th>Notes</th></tr></thead><tbody><tr><td>Atlas texture</td><td>274 MiB</td><td>548 MiB</td><td>660³ × 1 or 2 bytes, per channel</td></tr><tr><td>Indirection table</td><td>8 KiB</td><td>8 KiB</td><td>16 × 8 × 16 cells × 4 bytes</td></tr><tr><td>Brick indices (CPU)</td><td>~0.3 MiB</td><td>~0.3 MiB</td><td>JSON, sharded binary only</td></tr><tr><td>Label pool</td><td>0–512 MiB</td><td>0–512 MiB</td><td>Only while <a href="/rendering/labels.html">labels</a> are shown: 574 KB per label brick with more than one ID, grows as needed up to <code>labelBudgetBytes</code></td></tr><tr><td>Render targets</td><td>24 B/pixel per render scale</td><td>same</td><td>Output and two accumulation textures (rgba16float) for every render scale a view has used, per view, plus a full-size depth buffer. A 1920 × 1080 view at render scales 1 and 0.25 holds about 58 MiB</td></tr></tbody></table><p>With more channels the atlas grid shrinks to stay within the budget; see <a href="/architecture/virtual-texturing.html#multichannel-atlas">Multichannel atlas</a>.</p><p>CPU-side caches come on top: decompressed bricks for re-upload after atlas eviction (256 MiB per channel) and, for Zarr, decoded chunks in each worker (64–256 MiB per worker, sized to the chunk size).</p><h2 id="reading-the-numbers" tabindex="-1">Reading the numbers <a class="header-anchor" href="#reading-the-numbers" aria-label="Permalink to &quot;Reading the numbers&quot;">​</a></h2><p><code>KilnEngine.getMemoryStats()</code> (also on <code>KilnViewer</code>) returns what is held now: GPU bytes by atlas, render targets, labels and the rest; both caches with their budgets and hit rates; the JS heap where the browser exposes it; and the pressure counters, that is atlas evictions, refused allocations, brick-cache evictions and label pool growth. A rising count of refused allocations means the atlas budget is too small for the view; a brick-cache hit rate near zero after moving the camera means the cache budget is. The viewers show the same numbers in the stats panel (<code>?debug=1</code>, <strong>Memory</strong>), and <code>?bench=1</code> records them with their peaks; see <a href="/guide/url-parameters.html#diagnostics-and-experiments">URL parameters</a>.</p>',7)])])}const b=t(o,[["render",s]]);export{u as __pageData,b as default};
